// src/lib/pdfTemplateData.ts
// Pre-bundled base64 Navy templates and Courier Prime font.
// Allows APEX v2 to run 100% offline via file:/// protocol without CORS fetch blocks.

export const TEMPLATE_BASE64 = {
  EVAL: "",
  CHIEFEVAL: "",
  FITREP: "",
};

export const COURIER_PRIME_BASE64 = "";

export function base64ToUint8Array(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}
